"""Second pass: 6,217 -> ~5,000 words by moving protocol detail to the supplement."""
import pathlib
import re

P = pathlib.Path("outputs/paper/manuscript.en.md")
s = P.read_text(encoding="utf-8")
n = 0


def rep(old, new):
    global s, n
    if old not in s:
        print("MISS:", old[:70].replace("\n", " "))
        return
    s = s.replace(old, new, 1)
    n += 1


